#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include "h3api.h"
#include "polygon.h"
#include "polyfill.h"
static void check(LatLng a, LatLng b, int res){
 LatLng v[2]={a,b}; GeoPolygon p={.geoloop={.numVerts=2,.verts=v},.numHoles=0,.holes=NULL};
 int64_t sz=0; if(maxPolygonToCellsSizeExperimental(&p,res,CONTAINMENT_OVERLAPPING,&sz)||sz<0||sz>200000) return;
 H3Index *out=calloc(sz+200000,sizeof(H3Index)); if(!out) return;
 H3Error e=polygonToCellsExperimental(&p,res,CONTAINMENT_OVERLAPPING,out);
 int64_t cnt=0; while(cnt<sz+200000 && out[cnt]) cnt++;
 free(out);
 if(!e && cnt>sz){printf("FOUND res=%d sz=%ld cnt=%ld\n%.17g %.17g\n%.17g %.17g\n",res,(long)sz,(long)cnt,a.lat,a.lng,b.lat,b.lng); exit(0);} }
int main(){srand(3); for(int res=0;res<=8;res++){fprintf(stderr,"res %d\n",res); for(int t=0;t<200000;t++){
 double lat1=((double)rand()/RAND_MAX)*M_PI-M_PI_2; double lng1=((double)rand()/RAND_MAX)*2*M_PI-M_PI;
 double ang=((double)rand()/RAND_MAX)*2*M_PI; double len=pow(10, ((double)rand()/RAND_MAX)*1.8 - 2.0); // .01..0.63
 LatLng a={lat1,lng1}, b={lat1+len*sin(ang), lng1+len*cos(ang)};
 if(b.lat<-M_PI_2||b.lat>M_PI_2||b.lng<-M_PI||b.lng>M_PI) continue; check(a,b,res);
 }} return 1;}
EOF
gcc -O3 -I/tmp/h3build/include -Isrc/apps/applib/include src/h3lib/lib/*.c /tmp/search_lines.c -lm -o /tmp/search_lines && timeout 120 /tmp/search_lines

